<?php
defined('BASEPATH') OR exit('No direct script access allowed');
$title = $labels['employee_heading'];
$records = is_array($employee_records) ? $employee_records : array();
$filter_mode = isset($employee_filter_mode) && $employee_filter_mode === 'columns' ? 'columns' : 'search';
$sort = isset($employee_sort) && in_array($employee_sort, array('employee_code', 'employee_name'), TRUE) ? $employee_sort : 'employee_name';
$direction = isset($employee_direction) && $employee_direction === 'DESC' ? 'DESC' : 'ASC';
$employee_search = isset($employee_search) ? (string) $employee_search : '';
$employee_filter_code = isset($employee_filter_code) ? (string) $employee_filter_code : '';
$employee_filter_name = isset($employee_filter_name) ? (string) $employee_filter_name : '';
$employee_per_page = isset($employee_per_page) ? (int) $employee_per_page : 10;
$employee_page = max(1, isset($employee_page) ? (int) $employee_page : 1);
$employee_page_count = max(1, isset($employee_page_count) ? (int) $employee_page_count : 1);
$employee_age = function ($birth_date) {
    if (!is_string($birth_date) || !preg_match('/\\A\\d{4}-\\d{2}-\\d{2}\\z/', $birth_date)) { return ''; }
    $date = DateTime::createFromFormat('!Y-m-d', $birth_date);
    $errors = DateTime::getLastErrors();
    if (!$date || $date->format('Y-m-d') !== $birth_date || ($errors !== FALSE && ($errors['warning_count'] || $errors['error_count'])) || $date > new DateTime('today')) { return ''; }
    return $date->diff(new DateTime('today'))->y;
};
$params = array('filter_mode' => $filter_mode, 'per_page' => $employee_per_page, 'sort' => $sort, 'direction' => $direction);
if ($filter_mode === 'columns') {
    $params['employee_code'] = $employee_filter_code;
    $params['employee_name'] = $employee_filter_name;
} else {
    $params['search'] = $employee_search;
}
$page_params = $params;
$sort_url = function ($field) use ($params, $sort, $direction) {
    $next = $params;
    $next['sort'] = $field;
    $next['direction'] = $sort === $field && $direction === 'ASC' ? 'DESC' : 'ASC';
    return '/admin/hr/employee?' . http_build_query($next);
};
$employee_actions_available = (!empty($employee_can_update) && !empty($employee_write_available)) || (!empty($employee_can_delete) && !empty($employee_write_available));
