<script>(function(){var header=document.querySelector('[data-employee-filter-header]'),toggle=document.querySelector('[data-employee-filter-toggle]'),panel=document.querySelector('[data-employee-column-filter-panel]'),searchForm=document.querySelector('[data-employee-live-filter]'),searchInput=searchForm&&searchForm.querySelector('[name="search"]'),columnsIcon=toggle&&toggle.querySelector('[data-employee-filter-icon-columns]'),searchIcon=toggle&&toggle.querySelector('[data-employee-filter-icon-search]'),label=toggle&&toggle.querySelector('[data-employee-filter-label]'),timer=null;if(toggle&&panel){function setMode(columns){if(searchForm){searchForm.hidden=columns;searchForm.classList.toggle('hidden',columns);}panel.hidden=!columns;panel.classList.toggle('hidden',!columns);toggle.setAttribute('aria-expanded',columns?'true':'false');var text=columns?toggle.getAttribute('data-label-search'):toggle.getAttribute('data-label-columns');toggle.setAttribute('aria-label',text);toggle.setAttribute('title',text);if(label)label.textContent=text;if(columnsIcon){columnsIcon.hidden=columns;columnsIcon.classList.toggle('hidden',columns);}if(searchIcon){searchIcon.hidden=!columns;searchIcon.classList.toggle('hidden',!columns);}}toggle.addEventListener('click',function(){var columns=panel.hidden;setMode(columns);var field=columns?panel.querySelector('input[name="employee_code"]'):searchInput;if(field)field.focus();});document.addEventListener('click',function(event){if(header&&!header.contains(event.target)&&toggle.getAttribute('aria-expanded')==='true')setMode(false);});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){setMode(false);toggle.focus();}});}if(searchForm&&searchInput){searchForm.addEventListener('submit',function(){window.clearTimeout(timer);});searchInput.addEventListener('input',function(){window.clearTimeout(timer);timer=window.setTimeout(function(){if(searchForm.requestSubmit)searchForm.requestSubmit();else searchForm.submit();},350);});}document.querySelectorAll('[data-employee-menu-toggle]').forEach(function(button){button.addEventListener('click',function(){var menu=document.getElementById(button.getAttribute('aria-controls'));if(!menu)return;var open=button.getAttribute('aria-expanded')==='true';document.querySelectorAll('[data-employee-menu-toggle]').forEach(function(other){if(other!==button){other.setAttribute('aria-expanded','false');var otherMenu=document.getElementById(other.getAttribute('aria-controls'));if(otherMenu)otherMenu.hidden=true;}});button.setAttribute('aria-expanded',open?'false':'true');menu.hidden=open;if(!open){var rect=button.getBoundingClientRect(),size=menu.getBoundingClientRect(),top=rect.bottom+4,left=rect.right-size.width,maxTop=window.innerHeight-size.height-8,maxLeft=window.innerWidth-size.width-8;if(top+size.height>window.innerHeight-8)top=rect.top-size.height-4;menu.style.top=Math.max(8,Math.min(top,maxTop))+'px';menu.style.left=Math.max(8,Math.min(left,maxLeft))+'px';var first=menu.querySelector('[role="menuitem"]');if(first)first.focus();}});});document.addEventListener('click',function(event){if(!event.target.closest('[data-employee-menu-toggle]')&&!event.target.closest('[role="menu"]'))document.querySelectorAll('[data-employee-menu-toggle]').forEach(function(button){button.setAttribute('aria-expanded','false');var menu=document.getElementById(button.getAttribute('aria-controls'));if(menu)menu.hidden=true;});});document.addEventListener('keydown',function(event){if(event.key==='Escape'){document.querySelectorAll('[data-employee-menu-toggle][aria-expanded="true"]').forEach(function(button){button.setAttribute('aria-expanded','false');var menu=document.getElementById(button.getAttribute('aria-controls'));if(menu)menu.hidden=true;button.focus();});}});})();</script>
